const $=s=>document.querySelector(s),logEl=$('#log-text');
function setLog(t){logEl.textContent=t.toUpperCase()}
function playTone(freq=240,duration=.08,type='sawtooth',gain=.04){if(!soundOn)return;try{audioCtx ||= new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(gain,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function setMeter(id,value,max=100){$(id).style.width=`${Math.max(0,value/max*100)}%`}
function updateHUD(){setMeter('#player-hp',player.health);$('#player-hp-text').textContent=Math.ceil(player.health);setMeter('#stamina-bar',player.stamina);$('#stamina-text').textContent=Math.floor(player.stamina);setMeter('#enemy-hp',enemy.health);$('#enemy-hp-text').textContent=Math.ceil(enemy.health);setMeter('#armor-bar',enemy.armorIntegrity);$('#armor-text').textContent=Math.ceil(enemy.armorIntegrity)}
function setToast(name){$('#loot-name').textContent=name;$('#loot-toast').classList.add('show');toastTimer=3.1}
function particlesAt(position,color=0xe7a55e,count=12,power=2.2){for(let i=0;i<count;i++){const p=mesh(new THREE.SphereGeometry(.035+Math.random()*.035,6,6),new THREE.MeshBasicMaterial({color,transparent:true}),scene,position.clone());const v=new THREE.Vector3((Math.random()-.5)*power,Math.random()*power*.8,(Math.random()-.5)*power);p.userData={velocity:v,life:.45+Math.random()*.45};dust.push(p)}}
