function setKeyAction(key,down){if(key==='w'||key==='arrowup')walkInput.z=down?-1:walkInput.z===-1?0:walkInput.z;if(key==='s'||key==='arrowdown')walkInput.z=down?1:walkInput.z===1?0:walkInput.z;if(key==='a'||key==='arrowleft')walkInput.x=down?-1:walkInput.x===-1?0:walkInput.x;if(key==='d'||key==='arrowright')walkInput.x=down?1:walkInput.x===1?0:walkInput.x}
