function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<620?48:42;camera.position.set(0,innerWidth<620?9.5:8.4,innerWidth<620?19:15.8);camera.lookAt(0,1.3,0);camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);
function animateFighter(f,dt,time){f.attackCooldown=Math.max(0,f.attackCooldown-dt);f.stun=Math.max(0,f.stun-dt);f.dodge=Math.max(0,f.dodge-dt);f.hurt=Math.max(0,f.hurt-dt);f.jump=Math.max(0,f.jump-dt*1.35);f.stamina=Math.min(100,f.stamina+dt*(f.guard?6:14));if(f===player&&f.injuries>=2&&f.stamina<35)f.stamina=Math.min(f.stamina,40);f.root.position.y=f.jump>0?Math.sin((1-f.jump)*Math.PI)*.9:0;f.body.position.y=f.jump>0?0:Math.sin(time*9)*Math.min(.035,f.walk*.012);f.body.rotation.z=THREE.MathUtils.damp(f.body.rotation.z,0,5,dt);f.body.rotation.x=f.guard?-.12:0;
